#include <iostream>

// Global constant
constexpr int kMultiplier = 2;

int counter_call() {
    // Local static persists across calls, initialized once
    static int call_count = 0;
    call_count++;
    return call_count;
}

int main() {
    std::cout << counter_call() * kMultiplier << "\n";
    std::cout << counter_call() * kMultiplier << "\n";
    std::cout << counter_call() * kMultiplier << "\n";
    return 0;
}
